from packaging.markers import Marker
from typing import Dict, List, Optional, Union


def evaluate_marker(marker: str, environment: Optional[Dict[str, Union[str, List[str]]]] = None, context: Optional[str] = None) -> bool:
    """Evaluates a package marker expression against an environment and returns true or false. Markers define conditions for dependencies. Parameters: 'marker' (string, e.g., 'python_version >= '3.6''), 'environment' (optional mapping of environment variables), 'context' (string, one of 'metadata', 'lock_file', or 'requirement'). Returns a boolean indicating whether the marker matches the environment."""
