def create_singleton_version_range(version: str, prereleases: bool | None = None) -> str:
    """Returns a version range that includes exactly one PEP 440 version and excludes local versions. 'version' is a string like '1.0.0'. 'prereleases' is a bool or null (default null): use null to exclude prereleases, or set to true to include them. Output is a JSON string like '<VersionRange '[1.0.0, 1.0.0]' pre=False>'."""
