def intersect_version_ranges(range1: str, range2: str) -> str:
    """Compute the intersection of two version ranges. range1: First version range specifier, range2: Second version range specifier. Example: intersect_version_ranges(">=1.0", "<2.0") -> ">=1.0,<2.0"."""
    try:
        vr1 = SpecifierSet(range1).to_range()
        vr2 = SpecifierSet(range2).to_range()
        result = vr1.intersection(vr2)
        return str(result)
    except Exception as e:
        raise ValueError(f"Invalid version range specification: {e}")

