from packaging.tags import parse_tag as _parse_tag


def parse_tag(tag: str, validate_order: bool = False, limit: int | None = None) -> frozenset[str]:
    """Parse a tag string into a frozenset of Tag instances. tag: The tag to parse, e.g. "py3-none-any". validate_order: Check whether compressed tag set components are in sorted order. limit: The maximum number of tags to parse. -> frozenset of tag strings."""
