from typing import List, Optional
from packaging.tags import cpython_tags, Tag


def generate_cpython_tags(
    python_version: Optional[List[int]] = None,
    abis: Optional[List[str]] = None,
    platforms: Optional[List[str]] = None
) -> List[dict]:
    """Generate CPython interpreter tags for wheel compatibility. python_version: target Python version as [major, minor], e.g. [3, 9]. abis: compatible ABIs like ['cp39', 'abi3'], defaults to system-compatible. platforms: compatible platforms like ['linux_x86_64'], defaults to system-compatible. Example: generate_cpython_tags([3, 9]) -> [{'interpreter': 'cp39', 'abi': 'cp39', 'platform': 'linux_x86_64'}]"""

    try:
        tags = []
        for tag in cpython_tags(python_version, abis, platforms):
            tags.append({
                "interpreter": tag.interpreter,
                "abi": tag.abi,
                "platform": tag.platform
            })
        return tags
    except Exception as e:
        raise ValueError(f"Failed to generate CPython tags: {str(e)}")

